using OcctSharp.ConstructionWorkspaces;
using OcctSharp.MeshProximity;
using OcctSharp.Tests.Shared;
namespace OcctSharp.Runtime.Tests;
public sealed class MeshProximityTests {
 [Fact]public void VisitedDisjointTrianglesPreserveNativeDoneWithEmptyExactRelation(){using var face=BatchBOMeshProximityWorkflow.Face();using var a=MeshTopology.ReplaceTriangulation(face,0,new([new(0,0,0),new(4,0,0),new(0,4,0)],[new(0,1,2)]));using var b=MeshTopology.ReplaceTriangulation(face,0,new([new(3,3,0),new(4,3,0),new(3,4,0)],[new(0,1,2)]));using var r=MeshProximityComputations.Compute(a,b);Assert.True(r.WasPerformed);Assert.True(r.IsDone);Assert.Empty(r.Pairs);Assert.Null(r.Reference);}
 [Fact]public void RealBlFaceMeshingNativeOverlapAndProximityWorkflow()=>BatchBOMeshProximityWorkflow.Run();
 [Theory][InlineData(.99,0)][InlineData(1.01,1)]public void FiniteToleranceKeepsNativeInsideOutsideRelation(double tolerance,int pairs){using var a=BatchBOMeshProximityWorkflow.Face();using var b=BatchBOMeshProximityWorkflow.Face(1);using var r=MeshProximityComputations.Compute(a,b,new(Tolerance:tolerance));Assert.True(r.WasPerformed);Assert.Equal(pairs!=0,r.IsDone);Assert.Equal(pairs,r.Pairs.Count);Assert.Equal(tolerance,r.RequestedTolerance);Assert.Null(r.LayerThickness);Assert.Null(r.Reference);}
 [Fact]public void DifferentMeshDensitiesPreserveExactFacePairingAndNativeRefinement(){using var a=BatchBOMeshProximityWorkflow.Face();using var b=BatchBOMeshProximityWorkflow.Face(1,4);using var overlap=MeshProximityComputations.Compute(a,b,new(Tolerance:1.01));Assert.Single(overlap.Pairs);Assert.Equal(2,overlap.FirstTriangles);Assert.Equal(32,overlap.SecondTriangles);using var value=MeshProximityComputations.Compute(a,b,new(Mode:MeshProximityMode.LayerThickness));Assert.True(value.IsDone);Assert.Equal(1,value.LayerThickness!.Value,5);Assert.NotNull(value.Reference);Assert.Throws<ArgumentException>(()=>MeshProximityComputations.Compute(a,b,new(Mode:MeshProximityMode.LayerThickness,MaximumRefinementSplits:0)));}
 [Fact]public void MultiFaceOverlapPreservesExactInputIndicesAndPairBudget(){using var a=BatchBOMeshProximityWorkflow.Face();using var b=BatchBOMeshProximityWorkflow.Face(1);using var assembly=ShapeFactory.CreateCompound([a,b]);using var r=MeshProximityComputations.Compute(assembly,assembly);Assert.True(r.IsDone);Assert.Equal(new[]{new MeshOverlapPair(0,0),new MeshOverlapPair(1,1)},r.Pairs);using var face=r.CopyFace(0,1);Assert.Equal(1,face.GetBoundingBox().Minimum.Z,5);Assert.Throws<ArgumentException>(()=>MeshProximityComputations.Compute(assembly,assembly,new(MaximumPairs:1)));Assert.Throws<ArgumentException>(()=>MeshProximityComputations.Compute(assembly,assembly,new(Mode:MeshProximityMode.LayerThickness)));}
 [Fact]public void MissingResidentMeshesAndStandaloneEdgePolygonsAreRejected(){using var unmeshed=ParameterizedConstruction.AnalyticFace(AnalyticConstructionSurface.Plane,ConstructionFrame.World,0,4,0,4);using var face=unmeshed.CopyShape();using var mesh=BatchBOMeshProximityWorkflow.Face();Assert.Throws<ArgumentException>(()=>MeshProximityComputations.Compute(face,mesh));using var poly=MeshTopology.CreatePolyline(new MeshPolyline3d([new(0,0,0),new(2,0,0)]));using var mixed=ShapeFactory.CreateCompound([mesh,poly]);Assert.Throws<ArgumentException>(()=>MeshProximityComputations.Compute(mixed,mesh));}
 [Fact]public void RepeatedAndDegenerateTrianglesAreRejectedBeforeNativeComputation(){using var a=BatchBOMeshProximityWorkflow.Face();using var repeated=MeshTopology.ReplaceTriangulation(a,0,new([new(0,0,0),new(4,0,0),new(4,4,0)],[new(0,1,1)]));Assert.Throws<ArgumentException>(()=>MeshProximityComputations.Compute(a,repeated));using var flat=MeshTopology.ReplaceTriangulation(a,0,new([new(0,0,0),new(2,0,0),new(4,0,0)],[new(0,1,2)]));Assert.Throws<ArgumentException>(()=>MeshProximityComputations.Compute(a,flat));}
 [Theory][InlineData(-1)][InlineData(double.NaN)][InlineData(double.PositiveInfinity)]public void InvalidFiniteTolerancesAreRejected(double tolerance){using var a=BatchBOMeshProximityWorkflow.Face();Assert.Throws<ArgumentException>(()=>MeshProximityComputations.Compute(a,a,new(Tolerance:tolerance)));}
 [Fact]public void InputAndOutputBudgetsRejectBeforePublishingOwner(){using var a=BatchBOMeshProximityWorkflow.Face();Assert.Throws<ArgumentException>(()=>MeshProximityComputations.Compute(a,a,new(MaximumNodes:3)));Assert.Throws<ArgumentException>(()=>MeshProximityComputations.Compute(a,a,new(MaximumTriangles:1)));Assert.Throws<ArgumentException>(()=>MeshProximityComputations.Compute(a,a,new(MaximumFaces:0)));Assert.Throws<ArgumentException>(()=>MeshProximityComputations.Compute(a,a,new(MaximumPairs:0)));Assert.Throws<ArgumentException>(()=>MeshProximityComputations.Compute(a,a,new(Mode:MeshProximityMode.LayerThickness,FirstSamples:5)));Assert.Throws<ArgumentException>(()=>MeshProximityComputations.Compute(a,a,new(FirstSamples:1)));Assert.Throws<ArgumentException>(()=>MeshProximityComputations.Compute(a,a,new(Mode:MeshProximityMode.LayerThickness,Tolerance:1)));}
 [Fact]public void SourceReplacementAndClosureDoNotChangeFrozenMetadataOrQueryCopies(){using var a=BatchBOMeshProximityWorkflow.Face();using var b=BatchBOMeshProximityWorkflow.Face();using var r=MeshProximityComputations.Compute(a,b);using var changed=MeshTopology.ReplaceTriangulation(a,0,BatchBOMeshProximityWorkflow.Grid(100,4));a.Dispose();b.Dispose();Assert.Equal(2,r.FirstTriangles);Assert.Single(r.Pairs);using var first=r.CopyFace(0,0);using var second=r.CopyFace(0,0);r.Dispose();Assert.Equal(0,first.GetBoundingBox().Minimum.Z,5);Assert.Equal(2,MeshTopology.SnapshotExisting(second).Mesh.Triangles.Count);Assert.Throws<ObjectDisposedException>(()=>r.CopyFace(0,0));Assert.Single(r.Pairs);}
 [Fact]public void QueryIndicesAndClosedInputsAreRejected(){using var a=BatchBOMeshProximityWorkflow.Face();using var r=MeshProximityComputations.Compute(a,a);Assert.Throws<ArgumentOutOfRangeException>(()=>r.CopyFace(2,0));Assert.Throws<ArgumentOutOfRangeException>(()=>r.CopyFace(0,1));a.Dispose();Assert.Throws<ObjectDisposedException>(()=>MeshProximityComputations.Compute(a,a));}
 [Fact]public void ConcurrentFaceQueriesAndReleaseKeepDetachedCopiesValid(){using var a=BatchBOMeshProximityWorkflow.Face();var r=MeshProximityComputations.Compute(a,a);var copies=new System.Collections.Concurrent.ConcurrentBag<Shape>();Parallel.For(0,64,i=>{try{copies.Add(r.CopyFace(0,0));}catch(ObjectDisposedException){}if(i==5)r.Dispose();});r.Dispose();foreach(var face in copies){Assert.Equal(2,MeshTopology.SnapshotExisting(face).Mesh.Triangles.Count);face.Dispose();}}
}
